"use strict";const t=require("../utils/request.js");exports.budgetOverview=function(e){return t.http.get(`/budgets?month=${encodeURIComponent(e)}`)},exports.copyPreviousBudget=function(e){return t.http.post(`/budgets/copy-previous?month=${encodeURIComponent(e)}`)},exports.deleteCategoryBudget=function(e,o){return t.http.del(`/budgets/categories/${o}?month=${encodeURIComponent(e)}`)},exports.setCategoryBudget=function(e,o,n){return t.http.post(`/budgets/categories?month=${encodeURIComponent(e)}`,{categoryId:o,amount:n})},exports.setTotalBudget=function(e,o){return t.http.put(`/budgets?month=${encodeURIComponent(e)}`,{amount:o})};
